import XCTest
@testable import LinkPoolCore

final class SrunCryptoTests: XCTestCase {
    /// Golden vector generated by the Python reference implementation
    /// (/tmp/srunref/ref.py). Changing this test means changing the protocol.
    func testUserInfoGoldenVector() {
        let info = SrunCrypto.encodeUserInfo(
            json: "{\"username\":\"tls0228\",\"password\":\"p@ssw0rd\",\"ip\":\"10.10.55.234\",\"acid\":\"1\",\"enc_ver\":\"srun_bx1\"}",
            token: "0123456789abcdef0123456789abcdef01234567"
        )
        XCTAssertEqual(info, "{SRBX1}YOtik0UKTQ+G315i7c1caFAAIm1SixcGo9KTkHNnUBpmSGuFIOXDcd4pyUGixkHisuUjILV7Q7vEQ3rVb8+syxZXHqKGVd3qntj3ZlkB5ZVY+P0p+3fbFRvTIc5jRxxdZ4ofJL==")
    }

    func testUserInfoUnicode() {
        let info = SrunCrypto.encodeUserInfo(
            json: "{\"username\":\"2023001\",\"password\":\"密码123\",\"ip\":\"10.20.30.40\",\"acid\":\"12\",\"enc_ver\":\"srun_bx1\"}",
            token: "a1b2c3d4e5f60718293a4b5c6d7e8f9012345678"
        )
        XCTAssertEqual(info, "{SRBX1}DpXRPPbgWj+zp2gYV2I+ED6koSxkn95DCgBvVT43u+DecB8ak1TnrmAE6gQ7gm2uL7R4yHG+ASkDdGtgDQkHeHE/TbSITGwU0yM2WSPq+ZLyAmM05Jwmyd75YckBpx5QLMr+lBu1gEM=")
    }

    func testEncodeVectors() {
        let vectors: [(String, String, String)] = [
            ("odJFCrnl2edlBD:dz1C5Jau2RJtBRnlWmTSHf6pWk", "9b62179273c8eb5bb682575ec87a171ac826a6fc", "RUhc8FSmrCQGbw/pnU0ovouVilAVshE2gJ0cuEbafYUXH94hJ8V0ieT4tfnpqbTU"),
            ("6sHrFH2ZUCr\"}lgotu2iXW7GboIRoL3u6aH:w:nM:ztVuaP{coUNEhEkk", "f244f58d669cbee3772a077021721a278f64f7fd", "Da9Ikv4WOhCIWlxjZFA7lcmMWYpwLyhAoZYBqtb4JF+AlUS8o6QxLk/45vMQGwMGvzZxwT7+ABB8YtEzmQaBAw=="),
            ("mm3T207gmhZRn", "766e4d58e72e310275dff6c15c0c8e9df469611a", "ay5CBMFb7Ehr+STos41xE1GxVHQ="),
            ("g9:u", "125227c3712da86a78c49ea20e32684b27b95e90", "4837KOaje24="),
            ("MnrHontIKARAH:{Ggl2JfaQqHu42bojteVs3qfNUfTA", "73bd4755d05ad7853c1f76eb97706ca828bca038", "LRmW5qi1YJ5nVSZLWsRjYAKKtXrXx8Ed6uuLFlHxPt8hSCzzKcLegnKBYCkrV8fs"),
        ]
        for (message, key, expected) in vectors {
            let out = SrunCrypto.xEncode(Array(message.utf8), key: Array(key.utf8))
            XCTAssertEqual(Data(out).base64EncodedString(), expected, "xencode mismatch for \(message)")
        }
    }

    func testHashes() {
        XCTAssertEqual(SrunCrypto.md5Hex("password"), "5f4dcc3b5aa765d61d8327deb882cf99")
        XCTAssertEqual(SrunCrypto.hmacMD5Hex(key: "key", message: "The quick brown fox jumps over the lazy dog"),
                       "80070713463e7749b90c2dc24911e275")
        XCTAssertEqual(SrunCrypto.sha1Hex("abc"), "a9993e364706816aba3e25717850c26c9cd0d89d")
    }

    func testEmptyEncoding() {
        XCTAssertEqual(SrunCrypto.xEncode([], key: [1, 2, 3]), [])
    }
}
